    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await handleListSessions(ws, session, message, sessionStore);
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore?: SessionStore
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const rawSessions = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before,
    });
    const sessions: SessionSummaryFrame[] = rawSessions.map(summary => ({
      sessionId: summary.sessionId,
      createdAt: new Date(summary.createdAt).toISOString(),
      updatedAt: new Date(summary.updatedAt).toISOString(),
      entryCount: summary.entryCount,
    }));
    sendSessionList(ws, sessions);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'list_sessions failed', {userId: session.userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

